from pydantic_ai import Agent, ModelRetry, RunContext

agent = Agent('openai:gpt-5.2')

@agent.output_validator
def validate_output(ctx: RunContext, output: str) -> str:
    if ctx.partial_output:
        return output
    if len(output) < 50:
        raise ModelRetry('Output is too short.')
    return output

from pydantic_ai import Agent, ModelRetry

agent = Agent('openai:gpt-5.2')

@agent.tool_plain(retries=2)
def lookup_customer(customer_id: int) -> str:
    if customer_id <= 0:
        raise ModelRetry('customer_id must be positive')
    return f'customer:{customer_id}'

from pydantic_ai import Agent, RunContext

agent = Agent('google:gemini-3-flash-preview', deps_type=str)

@agent.tool
def get_player_name(ctx: RunContext[str]) -> str:
    return ctx.deps

result = agent.run_sync('What is my name?', deps='Anne')

from dataclasses import dataclass
from pydantic_ai import Agent, RunContext

@dataclass
class Deps:
    tenant: str

agent = Agent('openai:gpt-5.2', deps_type=Deps)

@agent.instructions
def tenant_instruction(ctx: RunContext[Deps]) -> str:
    return f'Tenant: {ctx.deps.tenant}'

result = agent.run_sync('Summarise my account', deps=Deps(tenant='acme'))
